// offset_hours > 0 = reminder fires that many hours BEFORE the appointment
// (e.g. 24 = day-before, 2 = hours-before). offset_hours <= 0 = fires
// |offset_hours| AFTER the appointment time (no-show follow-up).
const row = $input.item.json;
const dueAt = new Date(row.due_at).getTime() - row.offset_hours * 3600000;
const now = Date.now();
const catchWindowMs = 6 * 3600000; // tolerate up to 6h of engine downtime without skipping a reminder
const due = now >= dueAt && now < dueAt + catchWindowMs;

function fill(template) {
  const apptDateObj = new Date(row.due_at);
  const apptDate = apptDateObj.toLocaleString('en-US', { dateStyle: 'full', timeStyle: 'short' });
  return (template || '')
    .replace(/{{\s*user\.company_name\s*}}/gi, row.our_company_name || '')
    .replace(/{{\s*contact\.first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*contact\.last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*contact\.email\s*}}/gi, row.email || '')
    .replace(/{{\s*contact\.phone\s*}}/gi, row.phone || '')
    .replace(/{{\s*contact\.address\s*}}/gi, [row.city, row.state].filter(Boolean).join(', '))
    .replace(/{{\s*company\.name\s*}}/gi, row.client_company_name || '')
    .replace(/{{\s*user\.full_name\s*}}/gi, row.owner_name || 'your account team')
    .replace(/{{\s*user\.email\s*}}/gi, row.owner_email || '')
    .replace(/{{\s*user\.phone\s*}}/gi, row.owner_phone || '')
    .replace(/{{\s*opportunity\.name\s*}}/gi, row.opportunity_name || '')
    .replace(/{{\s*appointment\.start_time\s*}}/gi, apptDate);
}

let base = '';
try { base = $env.FRONTEND_BASE_URL || ''; } catch (e) { base = ''; }
const unsubUrl = base + '/unsubscribe/' + (row.unsubscribe_token || '');
const body = fill(row.email_body) + `

Don't want these emails? Unsubscribe: ${unsubUrl}`;

return [{
  json: {
    due,
    stepId: row.step_id,
    opportunityId: row.opportunity_id,
    activityId: row.activity_id,
    contactId: row.contact_id,
    to: row.email,
    subject: fill(row.email_subject),
    body,
  },
}];

